module Top;
  typedef int map_t[string];
  function automatic map_t make(int v);
    return '{"a": v, default: 0};
  endfunction
  initial begin
    map_t m;
    m = '{"a": 1, "b": 2, default: 9};
    $display("[%0d %0d %0d %0d]", m.size(), m["a"], m["b"], m["zz"]);
    m = make(5);
    $display("[%0d %0d %0d]", m.size(), m["a"], m["q"]);
  end
endmodule
